begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
create temp table instructions(pid uuid,result jsonb,payload jsonb,mail uuid,invite uuid);
insert into instructions(payload) values('{"name":"De Lantaarnpoort","worldSlug":"anders","contactName":"Lantaarnteam","contactEmail":"parent-size-5@example.invalid","lifecycleStatus":"concept","approvalStatus":"draft","commandKey":"manual-instruction-create-01"}');
update instructions set result=api.admin_manual_portal_save('duindorp-halloween-2026',null,payload,null,'Synthetische handmatige conceptpoort toevoegen');
update instructions set pid=(result->>'id')::uuid;
update instructions set mail=(result->'instructions'->>'outboxId')::uuid,invite=(result->'instructions'->>'inviteId')::uuid;
select is((select count(*) from app_private.email_outbox where message_type='portal_manual_instructions' and payload->>'portalId'=(select pid::text from instructions)),1::bigint,'creation queues exactly one instruction mail');
select is((select role from app_private.portal_team_invites where id=(select invite from instructions)),'coadmin','invitation grants its actual coadmin role rather than claiming ownership');
select is((select count(*) from app_private.portal_owners where portal_id=(select pid from instructions)),0::bigint,'contact address alone creates no account access');
select ok(api.worker_manual_portal_instructions((select mail from instructions)) is not null,'draft instructions have a usable worker payload instead of INVITATION_UNAVAILABLE');
select matches(api.worker_manual_portal_instructions((select mail from instructions))->>'statusText','concept','draft mail explains pending activation');
select matches(api.worker_manual_portal_instructions((select mail from instructions))->>'actionPath','^/uitnodiging/poort/[a-f0-9]{64}$','draft instructions use the same verified personal invitation entry');
select is((select api.admin_manual_portal_save('duindorp-halloween-2026',null,payload,null,'Synthetische handmatige conceptpoort toevoegen') from instructions),(select result from instructions),'double save uses original receipt');
select is((select count(*) from app_private.portals where name='De Lantaarnpoort'),1::bigint,'double save does not create a second portal');
select throws_ok($$select api.admin_manual_portal_save('duindorp-halloween-2026',null,payload||'{"name":"Andere opdracht"}',null,'Synthetische handmatige conceptpoort toevoegen') from instructions$$,'P0001','IDEMPOTENCY_CONFLICT','same key cannot authorize different creation content');
select api.admin_manual_portal_save('duindorp-halloween-2026',pid,payload-'commandKey'||'{"name":"De Lantaarnpoort aangepast"}',(select version from app_private.portals where id=pid),'Gewone gegevenswijziging zonder nieuwe welkommail') from instructions;
select is((select count(*) from app_private.email_outbox where message_type='portal_manual_instructions' and payload->>'portalId'=(select pid::text from instructions)),1::bigint,'ordinary edit queues no welcome duplicate');
select lives_ok($$select api.admin_manual_portal_instructions(pid,(select version from app_private.portals where id=pid),'explicit-instruction-resend-01') from instructions$$,'deliberate resend queues a separately audited message');
select lives_ok($$select api.admin_manual_portal_instructions(pid,(select version from app_private.portals where id=pid),'explicit-instruction-resend-01') from instructions$$,'resend retry is idempotent');
select is((select count(*) from app_private.email_outbox where message_type='portal_manual_instructions' and payload->>'portalId'=(select pid::text from instructions)),2::bigint,'one creation and one deliberate resend');
update app_private.portal_team_invites set expires_at=now()-interval '1 second' where id=(select invite from instructions);
select is(api.worker_manual_portal_instructions((select mail from instructions)),null::jsonb,'expired invitation cannot materialize into a misleading mail');
select throws_ok($$select api.admin_manual_portal_save('duindorp-halloween-2026',null,'{"name":"Invalid contact","worldSlug":"anders","contactEmail":"invalid-address"}',null,'Geen ongeldige instructieontvanger toestaan')$$,'P0001','INVALID_EMAIL','invalid email is rejected before creation');
select ok(not has_function_privilege('authenticated','api.worker_manual_portal_instructions(uuid)','execute'),'only trusted worker can materialize personal invitation links');
update instructions set result=api.admin_manual_portal_instructions(pid,(select version from app_private.portals where id=pid),'active-verified-access-01');
update instructions set invite=(result->>'inviteId')::uuid,mail=(result->>'outboxId')::uuid;
select matches(api.worker_manual_portal_instructions((select mail from instructions))->>'actionPath','^/uitnodiging/poort/[a-f0-9]{64}$','active mail uses the existing personally verified invitation flow');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select api.portal_invitation_accept(app_private.poortkamer_invite_token((select invite from instructions)))$$,'42501','INVITATION_UNAVAILABLE','another verified account cannot take this invitation');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select lives_ok($$select api.portal_invitation_accept(app_private.poortkamer_invite_token((select invite from instructions)))$$,'only the matching verified account obtains the actual initial-owner access');
select is((select role from app_private.portal_owners where portal_id=(select pid from instructions) and user_id=auth.uid()),'owner','existing initial-owner rule makes the first verified recipient the true owner');
select ok(api.portal_invitation_check('invalid','wrong@example.invalid')=false,'invalid token cannot create concept membership');
select is((select approval_status::text from app_private.portals where id=(select pid from instructions)),'draft','verified recipient cannot approve their own concept');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select api.admin_manual_portal_save('duindorp-halloween-2026',pid,(payload-'commandKey')||'{"lifecycleStatus":"active","approvalStatus":"approved","latitude":52.09,"longitude":4.26,"plannedOpensAt":"2026-10-31T16:00:00Z","plannedClosesAt":"2026-10-31T21:00:00Z"}',(select version from app_private.portals where id=pid),'Synthetische poort bewust actief maken na volledigheidscontrole') from instructions;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select ok(exists(select 1 from jsonb_array_elements(api.participant_context('duindorp-halloween-2026')->'roles') r where r->>'key'='walker') and exists(select 1 from jsonb_array_elements(api.participant_context('duindorp-halloween-2026')->'roles') r where r->>'key'='homeowner'),'genuine parent and portal membership coexist');
select * from finish();
rollback;
